WITH filtered_order_items AS (SELECT * FROM order_items WHERE product_id IN (2, 3, 22, 33)), order_items_stats AS (SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(unit_price) AS max_unit_price FROM filtered_order_items GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, max_unit_price FROM order_items_stats;
